"""Initial program for the suite task; SCiEL evolves the EVOLVE-BLOCK."""
# EVOLVE-BLOCK-START
import time
from random import Random

def construct():
    def instance(n, k, p, seed):
        rng = Random(seed)
        edges = [(u, v) for u in range(k) for v in range(u + 1, k)]
        edges += [(u, v) for v in range(k, n) for u in range(k) if rng.random() < p]
        return sorted(edges)

    def solve_split(n, k, p, seed):
        rng = Random(seed)
        cross_adj = {}
        for v in range(k, n):
            neighbors = []
            for u in range(k):
                if rng.random() < p:
                    neighbors.append(u)
            cross_adj[v] = set(neighbors)

        cliques = []
        if k >= 2:
            cliques.append(list(range(k)))

        for v in range(k, n):
            for u in sorted(cross_adj[v]):
                cliques.append([u, v])

        return [[int(x) for x in c] for c in cliques]

    results = []
    for spec in ((30, 10, 0.7, 301), (60, 20, 0.7, 302), (90, 30, 0.7, 303)):
        n, k, p, seed = spec
        results.append(solve_split(n, k, p, seed))

    return results
# EVOLVE-BLOCK-END
